function bindFolds() {
  document.querySelectorAll("details[data-k]").forEach(d => {
    if (openFolds.has(d.dataset.k)) d.open = true;
    d.addEventListener("toggle", () =>
      d.open ? openFolds.add(d.dataset.k) : openFolds.delete(d.dataset.k));
  });
}
function render() {
  const hash = decodeURIComponent(location.hash.slice(1));
  const y = window.scrollY;
  $stats.innerHTML = statsHTML();
  $app.innerHTML = hash ? viewDetail(hash) : viewBoard();
  bindFolds();
  window.scrollTo(0, hash === lastHash ? y : 0);   // live reload keeps place; navigation goes to top
  lastHash = hash;
}

/* ---------- data + hot reload ---------- */
async function refresh() {
  try {
    const res = await fetch("/api/tasks", { cache: "no-store" });
    DB = await res.json();
    render();
  } catch (e) { /* server briefly away; SSE reconnect will retrigger */ }
}
function connect() {
  const es = new EventSource("/events");           // EventSource auto-reconnects
  es.onopen = () => { $conn.textContent = "live"; $conn.className = "live"; refresh(); };
  es.onmessage = refresh;
  es.onerror = () => { $conn.textContent = "reconnecting…"; $conn.className = "down"; };
}
window.addEventListener("hashchange", render);
connect();
refresh();
</script>
</body>

